import bpy

obj = bpy.data.objects.get("node_0")
mat = bpy.data.materials.get("Material.002")

res = {
    "material_nodes": [],
    "textures": []
}

if mat and mat.node_tree:
    for node in mat.node_tree.nodes:
        res["material_nodes"].append({"name": node.name, "type": node.type})
        if node.type == 'TEX_IMAGE' and node.image:
            res["textures"].append({
                "node": node.name,
                "image": node.image.name,
                "size": list(node.image.size),
                "filepath": node.image.filepath
            })

# Also check normal map node or displacement
normal_node = next((n for n in mat.node_tree.nodes if n.type == 'NORMAL_MAP'), None)
if normal_node:
    res["normal_strength"] = normal_node.inputs['Strength'].default_value

result = res

import bpy

obj = bpy.data.objects.get("node_0")
vg = obj.vertex_groups.get("Weapons_Arm")
