    for v in obj.data.vertices:
        for g in v.groups:
            if g.group == vg_idx and g.weight > 0.001:
                in_group += 1
                break

result = {
    "total_vertices": total,
    "in_weapons_arm_group": in_group,
    "group_name": vg.name if vg else None
}

