import bpy
import mathutils

# Rotate viewport 180 degrees around Z or orbit around to see the other side of the arm
for area in bpy.context.screen.areas:
    if area.type == 'VIEW_3D':
        for space in area.spaces:
            if space.type == 'VIEW_3D':
                r3d = space.region_3d
                # Orbit around
                rot = r3d.view_rotation
                # Let's rotate around view
                euler = rot.to_euler()
                euler.z += 3.14159  # 180 deg
                r3d.view_rotation = euler.to_quaternion()
                break

result = {"rotated": True}

